"""Real questions from an APB-slave run: arch re-asked the requirements' settled questions in other words."""

REQ_Q = [{'id': 'Q-R1', 'question': 'Does presetn assertion during the rising clock edge of an access phase (penable=1 on that edge) complete the write or cancel it? I.e., if presetn goes low coincident with the clock edge rising, does the write commit before the reset takes effect, or is the write cancelled?', 'default_assumption': 'Reset takes priority: if presetn is low at any point during the rising clock edge or immediately after, the write does not commit; DATA is forced to 0 asynchronously and synchronously post-reset.'}, {'id': 'Q-R2', 'question': "For read transfers to non-zero addresses, what shall prdata return? The spec states reads return 'undefined data (implementation-specific, likely zeros)'. Should the implementation tie prdata to 0, leave it at the previous read value, or is full undefined behavior acceptable for verification?", 'default_assumption': 'prdata for non-zero address reads is implementation-defined; verification shall not check the value of prdata on non-zero address reads. Most likely implementation: tie prdata to current DATA register value (same as zero address read) or leave at previous value.'}, {'id': 'Q-R3', 'question': 'Is the pready output combinatorially tied to 1, or is it a flop that is set to 1 during normal operation? Does pready require any reset logic beyond being held high?', 'default_assumption': "pready is combinatorially tied to constant 1 (not a registered signal). No reset-specific logic is required; pready is always 1 by design (e.g., assign pready = 1'b1)."}, {'id': 'Q-R4', 'question': 'During presetn assertion, is prdata asynchronously driven to 0 (combinatorial logic), or is it held at its last synchronous value and then forced to 0 on the next rising edge?', 'default_assumption': 'prdata is asynchronously forced to 0 by the reset signal (combinatorial mux or reset logic); no delay through the clock. prdata transitions to 0 within combinatorial delay of presetn assertion.'}]
ARCH_Q = [{'question': 'Does presetn assertion during the rising clock edge of an access phase (penable=1) complete the write or cancel it?', 'default_assumption': 'Reset takes priority: if presetn is low at any point during or immediately after the rising clock edge on which penable=1 and pwrite=1, the write does not commit. DATA is forced to 0 asynchronously; the synchronous clock edge data assignment is inhibited by the asynchronous reset.'}, {'question': 'For read transfers to non-zero addresses, what shall prdata return?', 'default_assumption': 'prdata for non-zero address reads is implementation-defined. This implementation drives prdata to 0 on non-zero address reads (same logic as write transfers or idle phases). Golden model does not verify prdata value on non-zero address read transactions.'}, {'question': 'Is pready combinatorially tied to 1, or is it a flop with reset logic?', 'default_assumption': "pready is combinatorially tied to constant 1 (assign pready = 1'b1). No reset-specific logic is required; pready is always 1 by design."}, {'question': 'Is prdata asynchronously forced to 0 on presetn, or held at last value until next clock edge?', 'default_assumption': 'prdata is asynchronously forced to 0 by combinatorial logic (ternary mux with ~presetn condition). prdata transitions to 0 within combinatorial delay of presetn assertion, not waiting for a clock edge.'}]
